/*Table structure for table `exam_attempts` */

DROP TABLE IF EXISTS `exam_attempts`;

CREATE TABLE `exam_attempts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `attempt_number` int(10) unsigned NOT NULL DEFAULT 1,
  `started_at` datetime DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `total_questions` int(10) unsigned NOT NULL DEFAULT 0,
  `correct_answers` int(10) unsigned NOT NULL DEFAULT 0,
  `wrong_answers` int(10) unsigned NOT NULL DEFAULT 0,
  `unanswered` int(10) unsigned NOT NULL DEFAULT 0,
  `total_score` decimal(8,2) NOT NULL DEFAULT 0.00,
  `score` decimal(8,2) NOT NULL DEFAULT 0.00,
  `duration_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `status` enum('not_started','in_progress','submitted','expired','cancelled') NOT NULL DEFAULT 'not_started',
  `passed` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `exam_attempts_exam_id_student_id_attempt_number_unique` (`exam_id`,`student_id`,`attempt_number`),
  KEY `exam_attempts_student_id_status_index` (`student_id`,`status`),
  KEY `exam_attempts_exam_id_status_index` (`exam_id`,`status`),
  CONSTRAINT `exam_attempts_exam_id_foreign` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`),
  CONSTRAINT `exam_attempts_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

