/*Table structure for table `question_banks` */

DROP TABLE IF EXISTS `question_banks`;

CREATE TABLE `question_banks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` bigint(20) unsigned NOT NULL,
  `code` varchar(100) NOT NULL,
  `type` enum('multiple_choice','true_false') NOT NULL,
  `question` text NOT NULL,
  `explanation` text DEFAULT NULL,
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `default_score` decimal(8,2) NOT NULL DEFAULT 1.00,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `question_banks_code_unique` (`code`),
  KEY `question_banks_subject_id_type_index` (`subject_id`,`type`),
  KEY `question_banks_subject_id_difficulty_index` (`subject_id`,`difficulty`),
  CONSTRAINT `question_banks_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

